def h_index(citations):
    n = len(citations)
    buckets = [0] * (n + 1)

    for c in citations:
        if c >= n:
            buckets[n] += 1
        else:
            buckets[c] += 1

    count = 0
    for i in range(n, -1, -1):
        count += buckets[i]
        if count >= i:
            return i

import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
citations = list(map(int, data[1:]))

print(h_index(citations))
